<header class="discovery-heading"><h1><?= $admin?'پیشنهادهای تجربه':'ثبت تجربه' ?></h1><p>عنوان و خلاصهٔ تجربه را ثبت کن؛ تیم مرشد برای گفت‌وگو و ثبت کامل تجربه با تو ارتباط می‌گیرد. این فرم تجربه را مستقیماً منتشر نمی‌کند.</p></header>
<?php if(!$admin): ?><section class="card section lead-form"><?= $this->start('/experience/submit') ?><?= $this->field('title','عنوان تجربه','text','',true,240) ?><label for="lead-summary">خلاصهٔ کوتاه تجربه</label><textarea id="lead-summary" name="summary" maxlength="2000" minlength="15" required><?= $this->val('summary') ?></textarea><button>ارسال برای بررسی</button></form></section><?php endif; ?>
<section class="section"><h2><?= $admin?'پیگیری و تماس با صاحب تجربه':'تجربه‌های ارسالی من' ?></h2><?php foreach($rows as $lead): ?><article class="card section"><h3><?= $this->h($lead['title']) ?></h3><p class="prose"><?= nl2br($this->h($lead['summary'])) ?></p><span class="badge"><?= $this->h(['open'=>'در انتظار بررسی','contacted'=>'تماس گرفته شد','closed'=>'بررسی پایان یافت'][$lead['state']]) ?></span><?php if($admin): ?><p><a href="<?= $this->h($this->url('/users/edit?id='.$lead['user_id'])) ?>"><?= $this->h($lead['display_name']) ?></a> · <bdi><?= $this->h($lead['phone']??'شماره ثبت نشده') ?></bdi></p><?= $this->start('/experience-leads/review') ?><input type="hidden" name="id" value="<?= $this->h($lead['id']) ?>"><label>وضعیت پیگیری<select name="state"><?php foreach(['open'=>'در انتظار بررسی','contacted'=>'تماس گرفته شد','closed'=>'بررسی پایان یافت'] as $key=>$label): ?><option value="<?= $key ?>" <?= $lead['state']===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><button>ثبت پیگیری</button></form><?php endif; ?></article><?php endforeach; ?><?php if(!$rows): ?><p class="muted">هنوز تجربه‌ای ارسال نشده است.</p><?php endif; ?></section>
